phone_stand.scad_template:
// Parametric Phone Stand
// The back support rises at the requested angle from the middle of
// the base, so its underside stays a printable slope and the loaded
// phone bears over the base footprint.
phone_width = ${phone_width};
angle = ${angle};
base_depth = ${base_depth};
thickness = ${thickness};
lip_height = ${lip_height};

w = phone_width + 10;
support_len = base_depth * 0.8;
// Foot placed so the support's FRONT FACE plane passes through the
// lip's inner top edge: the phone then rests flat on the face at the
// requested angle.  (A fixed mid-base foot left the face parallel to
// and 28 mm behind the phone plane, so every stand rested at ~45
// degrees regardless of the angle parameter.)
foot_y = max(2, thickness * 2
    - (lip_height - thickness * cos(angle)) * cos(angle) / sin(angle));

module phone_stand() {
    // Base plate
    cube([w, base_depth, thickness]);
    // Back support: inclined at `angle` above the bed, sunk into the
    // base so it joins on a solid face rather than an edge
    translate([0, foot_y, thickness * cos(angle)])
        rotate([angle - 90, 0, 0])
            cube([w, thickness, support_len]);
    // Side gussets bracing the support (45-degree hypotenuse)
    for (x = [0, w - thickness])
        translate([x, foot_y + thickness * 0.5, 0])
            rotate([90, 0, 90])
                linear_extrude(thickness)
                    polygon([[0, 0], [20, 0], [0, 20]]);
    // Front lip
    translate([0, thickness, 0])
        cube([w, thickness, lip_height]);
    // Side rails
    for (x = [0, w - thickness]) {
        translate([x, 0, 0])
            cube([thickness, base_depth * 0.4, lip_height]);
    }
}

phone_stand();

hook.scad_template:
// Parametric Wall Hook
// The side profile (plate, arm, J-curve, rounded tip) is drawn in
// 2D and extruded to width, so the hook prints lying on its side:
// no supports, and the layer lines wrap the J for strength.
hook_radius = ${hook_radius};
t = ${thickness};
width = ${width};
plate_height = ${plate_height};
screw_hole_dia = ${screw_hole_dia};

cx = t + hook_radius;        // J-curve center, out from the wall
cy = t + hook_radius;        // J-curve center height

module wall_hook() {
    difference() {
        linear_extrude(width)
            union() {
                // Mounting plate (against the wall at x=0)
                square([t, plate_height]);
                // Arm along the bottom, out to the curve
                square([cx, t]);
                // J-curve: half-annulus opening back toward the wall
                difference() {
                    translate([cx, cy]) circle(r = hook_radius + t, $fn = 60);
                    translate([cx, cy]) circle(r = hook_radius, $fn = 60);
                    // keep the half away from the wall
                    translate([cx - hook_radius - t - 1, cy - hook_radius - t - 1])
                        square([hook_radius + t + 1,
                                (hook_radius + t + 1) * 2]);
                }
                // Rounded tip at the top of the J
                translate([cx, cy + hook_radius + t / 2])
                    circle(d = t, $fn = 30);
            }
        // Screw hole through the plate (into the wall)
        translate([-0.1, plate_height * 0.7, width / 2])
            rotate([0, 90, 0])
                cylinder(h = t + 0.2, d = screw_hole_dia, $fn = 30);
    }
}

wall_hook();

cable_clip.scad_template:
// Parametric Cable Clip
// The clip's cross-section (base pad, gusseted throats, snap C-rings
// with the cable running along the clip) is one 2D profile extruded
// to the clip length: no supports, and the layer lines wrap each C
// so the snap flexes along the plastic.
cable_dia = ${cable_dia};
channels = ${channels};
base_w = ${base_width};

wall = 2;
or = cable_dia / 2 + wall;
pitch = max(base_w, cable_dia + wall * 2 + 2);
cy = 2 + cable_dia / 2 + 0.5;   // ring center above the base pad
open = cable_dia * 0.75;        // snap opening, narrower than the cable

module clip() {
    linear_extrude(base_w)
        union() {
            // Base pad
            square([pitch * channels, 2]);
            for (ch = [0:channels - 1]) {
                cx = pitch * (ch + 0.5);
                // Ring and gusset unioned FIRST, bore and entry cut
                // from both, so the gusset can never stand proud
                // inside the cable bore
                difference() {
                    union() {
                        translate([cx, cy]) circle(r = or, $fn = 40);
                        // Gusset joining ring to base
                        translate([cx - or * 0.75, 1.9])
                            square([or * 1.5, cy - 1.9]);
                    }
                    translate([cx, cy]) circle(d = cable_dia, $fn = 40);
                    // Entry opening at the top
                    translate([cx - open / 2, cy])
                        square([open, or + 1]);
                }
            }
        }
}

clip();

shelf_bracket.scad_template:
// Parametric Shelf Bracket
// The bracket's side profile (wall plate, shelf arm on top, and a
// real diagonal brace) is drawn in 2D and extruded to width, so it
// prints lying flat with the layer lines running the length of the
// brace -- loaded in-plane, where printed plastic is strongest.
arm = ${arm_length};
wall_arm = ${wall_length};
w = ${width};
t = ${thickness};
hole_d = ${hole_dia};

// Brace foot ABOVE the lower wall hole (which sits at 0.15 * arm),
// so the screw and its driver clear it
brace_lo = max(wall_arm * 0.35, t * 1.5 + 2);
// Where the brace centerline crosses the upper wall hole's axis —
// a driver tunnel is cut there
tunnel_x = t + (wall_arm * 0.6 - brace_lo)
    * (arm * 0.9 - t) / (wall_arm - t - brace_lo);
brace_x = arm * 0.9;

module bracket() {
    difference() {
        linear_extrude(w)
            union() {
                // Wall plate (against the wall at x=0)
                square([t, wall_arm]);
                // Shelf arm along the top
                translate([0, wall_arm - t])
                    square([arm, t]);
                // Diagonal brace from low on the wall to the arm tip
                polygon([[t, brace_lo - t * 1.4],
                         [t, brace_lo],
                         [brace_x, wall_arm - t + 0.1],
                         [brace_x - t * 1.4, wall_arm - t + 0.1]]);
            }
        // Wall mounting holes (into the wall)
        for (y = [wall_arm * 0.15, wall_arm * 0.6])
            translate([-0.1, y, w / 2])
                rotate([0, 90, 0])
                    cylinder(h = t + 0.2, d = hole_d, $fn = 30);
        // Shelf screw hole up through the arm tip
        translate([arm - t * 2, wall_arm - t - 0.1, w / 2])
            rotate([-90, 0, 0])
                cylinder(h = t + 0.2, d = hole_d * 0.8, $fn = 30);
        // Driver tunnel through the brace on the upper wall hole's
        // axis — teardrop section, so the horizontal bore needs no
        // supports
        translate([tunnel_x - 6, wall_arm * 0.6, w / 2])
            rotate([0, 90, 0])
                linear_extrude(12) {
                    circle(d = hole_d * 2, $fn = 24);
                    polygon([[-hole_d * 0.707, -hole_d * 0.707],
                             [-hole_d * 1.414, 0],
                             [-hole_d * 0.707, hole_d * 0.707]]);
                }
    }
}

bracket();

drawer_organizer.scad_template:
// Parametric Drawer Organizer
w = ${width};
d = ${depth};
h = ${height};
cols = ${cols};
rows = ${rows};
wall = ${wall};

module organizer() {
    cell_w = (w - wall * (cols + 1)) / cols;
    cell_d = (d - wall * (rows + 1)) / rows;
    difference() {
        cube([w, d, h]);
        for (c = [0:cols-1]) {
            for (r = [0:rows-1]) {
                translate([wall + c * (cell_w + wall), wall + r * (cell_d + wall), wall])
                    cube([cell_w, cell_d, h]);
            }
        }
    }
}

organizer();

sd_card_holder.scad_template:
// Parametric SD Card Holder
// A solid block with top-opening slots in two rows: SD cards in
// front, microSD behind.  Cards drop in from above and stand proud
// of the block so they can be gripped.  Every slot opens through
// the top face -- no sealed pockets, no supports.
sd_n = ${sd_slots};
micro_n = ${micro_slots};
wall = ${wall};

sd_w = 24.5; sd_h = 32.5; sd_t = 2.5;
micro_w = 11.5; micro_h = 15.5; micro_t = 1.5;
slot_gap = 1;

sd_pitch = sd_t + slot_gap + wall;
micro_pitch = micro_t + slot_gap + wall;
sd_row_w = sd_n * sd_pitch + wall;
micro_row_w = micro_n * micro_pitch + wall;
total_w = max(sd_row_w, micro_row_w);
sd_depth = sd_h * 0.6;        // slot depth; cards stand proud
micro_depth = micro_h * 0.6;
total_h = wall + sd_depth;
total_d = wall + (sd_w + 1) + wall
          + (micro_n > 0 ? (micro_w + 1) + wall : 0);

module holder() {
    difference() {
        cube([total_w, total_d, total_h]);
        // SD slots (front row), open through the top
        for (i = [0:sd_n - 1]) {
            translate([(total_w - sd_row_w) / 2 + wall + i * sd_pitch,
                       wall, total_h - sd_depth])
                cube([sd_t + slot_gap, sd_w + 1, sd_depth + 0.1]);
        }
        // MicroSD slots (back row), open through the top
        if (micro_n > 0) {
            for (i = [0:micro_n - 1]) {
                translate([(total_w - micro_row_w) / 2 + wall
                               + i * micro_pitch,
                           wall + sd_w + 1 + wall, total_h - micro_depth])
                    cube([micro_t + slot_gap, micro_w + 1,
                          micro_depth + 0.1]);
            }
        }
    }
}

holder();

coat_hook_multi.scad_template:
// Parametric Multi-Peg Coat Hook
// Prints flat on its back: the plate lies on the bed and the pegs
// rise as vertical posts.  Each peg root steps down through a boss
// and a steep cone so the cross-section change is gradual, and the
// mushroom tip keeps coats from sliding off.
pegs = ${pegs};
peg_l = ${peg_length};
peg_d = ${peg_dia};
sp = ${spacing};
ph = ${plate_height};
hd = ${hole_dia};
t = 5;

total_w = (pegs - 1) * sp + peg_d + 20;
first_x = 10 + peg_d / 2;

module peg() {
    // Root boss and steep cone: strong, and a gradual transition
    cylinder(h = 3, d = peg_d + 6, $fn = 30);
    translate([0, 0, 3])
        cylinder(h = 4.2, d1 = peg_d + 6, d2 = peg_d, $fn = 30);
    cylinder(h = peg_l - peg_d / 2, d = peg_d, $fn = 30);
    // Mushroom tip: sub-45-degree flare, then an upward dome
    translate([0, 0, peg_l - peg_d / 2 - 1.9])
        cylinder(h = 1.9, d1 = peg_d, d2 = peg_d + 3, $fn = 30);
    translate([0, 0, peg_l - peg_d / 2])
        intersection() {
            sphere(d = peg_d + 3, $fn = 30);
            cylinder(h = peg_d, d = peg_d + 3, $fn = 30);
        }
}

module coat_hook() {
    difference() {
        cube([total_w, ph, t]);
        // Mounting holes in the first and last peg gaps, clear of
        // the peg root bosses
        for (x = [first_x + sp / 2, total_w - first_x - sp / 2]) {
            translate([x, ph / 2, -0.1]) {
                cylinder(h = t + 0.2, d = hd, $fn = 20);
                // Countersink, steeper than 45 degrees
                translate([0, 0, t - hd * 0.35 + 0.1])
                    cylinder(h = hd * 0.35 + 0.1, d1 = hd, d2 = hd * 1.5,
                             $fn = 20);
            }
        }
    }
    for (i = [0:pegs - 1])
        translate([first_x + i * sp, ph / 2, t])
            peg();
}

coat_hook();

hinge_box.scad_template:
// Print-in-Place Hinge Box
// Two half-height trays side by side, joined by a living hinge at
// RIM level: folding the lid tray 180 degrees closes it rim-to-rim
// onto the base tray.  (The old hinge sat at bed level with a flat
// lid, so folding put the lid UNDER the box floor — it could never
// close.)  The hinge is a 2 mm printable bridge.
w = ${width};
d = ${depth};
h = ${height};
wall = ${wall};
segs = ${hinge_segments};

half_h = h / 2;
hinge_gap = 2;
hinge_t = 0.8;      // living hinge: thin by design, folds at the seam
seg_w = (w - wall) / segs;

module tray() {
    difference() {
        cube([w, d, half_h]);
        translate([wall, wall, wall])
            cube([w - wall * 2, d - wall * 2, half_h]);
    }
}

// Base tray
tray();
// Lid tray, folds over
translate([0, d + hinge_gap, 0])
    tray();
// Living hinge at the top of the two adjacent rims
for (i = [0:segs - 1])
    translate([wall / 2 + i * seg_w, d - 0.3, half_h - hinge_t])
        cube([seg_w * 0.6, hinge_gap + 0.6, hinge_t]);

funnel.scad_template:
// Parametric Funnel
// Prints mouth-down: the wide rim sits on the bed and the cone
// narrows upward to the spout, so every wall leans less than the
// overhang limit and bed contact is a full ring.  The whole wall is
// one revolved cross-section -- no stacked-solid seams.
md = ${mouth_dia};
sd = ${spout_dia};
h = ${height};
sl = ${spout_length};
wall = ${wall};

hc = h - sl;   // cone height

module funnel() {
    rotate_extrude($fn = 80)
        polygon([
            // outer boundary, bottom rim up to the spout tip
            [md / 2 + wall * 2, 0],
            [md / 2 + wall * 2, 3],
            [md / 2 + wall, 3],
            [sd / 2 + wall, 3 + hc],
            [sd / 2 + wall, 3 + hc + sl],
            // across the spout tip, then the bore back down
            [sd / 2, 3 + hc + sl],
            [sd / 2, 3 + hc],
            [md / 2, 3],
            [md / 2, 0],
        ]);
}

funnel();

measuring_scoop.scad_template:
// Parametric Measuring Scoop
// Cylindrical cup (exact volume: V = pi * r^2 * depth, filled level
// to the brim) with a flat handle that prints on the bed.
vol = ${volume_ml};
hl = ${handle_length};
wall = ${wall};

// Squat cylinder, depth == inner radius: r = (V / pi)^(1/3)
ir = pow(vol * 1000 / 3.14159, 1/3);
depth = ir;
handle_t = max(3.5, wall * 1.5);
handle_w = max(10, ir * 0.7);

module scoop() {
    // Cup and handle unioned FIRST, cavity cut LAST, so the handle
    // can never stand proud inside the calibrated bowl
    difference() {
        union() {
            cylinder(h = depth + wall, r = ir + wall, $fn = 80);
            // Handle: flat bar on the bed, tapering toward the end
            translate([0, -handle_w / 2, 0])
                hull() {
                    cube([ir + wall, handle_w, handle_t]);
                    translate([ir + wall + hl - 5, handle_w * 0.15, 0])
                        cube([5, handle_w * 0.7, handle_t]);
                }
        }
        translate([0, 0, wall])
            cylinder(h = depth + 0.1, r = ir, $fn = 80);
    }
}

scoop();

wall_plate_cover.scad_template:
// Parametric Wall Plate Cover
style = "${style}";
pw = ${plate_width};
ph = ${plate_height};
cr = ${corner_radius};
t = 3;

module rounded_rect(w, h, r) {
    if (r > 0) {
        hull() {
            for (x = [r, w-r]) for (y = [r, h-r])
                translate([x, y]) circle(r=r, $fn=20);
        }
    } else {
        square([w, h]);
    }
}

module plate() {
    difference() {
        // Plate body
        linear_extrude(height=t)
            rounded_rect(pw, ph, cr);
        // Center cutout based on style
        if (style == "single_toggle") {
            translate([pw/2, ph/2, -0.1])
                linear_extrude(height=t+0.2)
                    square([10, 28], center=true);
        }
        if (style == "double_toggle") {
            // Two gangs side by side on the standard 46 mm spacing,
            // each with its own vertical screw pair.  (The old layout
            // stacked the openings vertically ON the +-30 screw
            // positions, leaving the plate nothing to mount with.)
            for (dx = [-23.02, 23.02])
                translate([pw/2 + dx, ph/2, -0.1])
                    linear_extrude(height=t+0.2)
                        square([10, 28], center=true);
        }
        if (style == "outlet") {
            // Duplex: two receptacle-face openings 38.4 mm apart with
            // the single standard center screw between them
            for (dy = [-19.2, 19.2])
                translate([pw/2, ph/2 + dy, -0.1])
                    linear_extrude(height=t+0.2)
                        hull()
                            for (dx = [-4, 4])
                                translate([dx, 0])
                                    circle(d=26, $fn=40);
        }
        // Screw holes, per style
        if (style == "single_toggle")
            for (dy = [-30, 30])
                translate([pw/2, ph/2 + dy, -0.1])
                    cylinder(h=t+0.2, d=4, $fn=20);
        if (style == "double_toggle")
            for (dx = [-23.02, 23.02])
                for (dy = [-30, 30])
                    translate([pw/2 + dx, ph/2 + dy, -0.1])
                        cylinder(h=t+0.2, d=4, $fn=20);
        if (style == "outlet")
            translate([pw/2, ph/2, -0.1])
                cylinder(h=t+0.2, d=4, $fn=20);
    }
}

plate();

soap_dish.scad_template:
// Parametric Soap Dish — clean dish + separate tapered drain spout
$fn = 80;

w = ${width};
d = ${depth};
h = ${height};
ridges = ${ridge_count};
cr = ${corner_radius};
spout_w = ${spout_width};
spout_l = ${spout_length};
wall = 3;
floor = 3;

// Spout taper: tip is 65% of base width, gives a clear teardrop tongue
tip_w = spout_w * 0.65;

// Hull-corner radii for the spout (smaller than dish corners — reads
// as a refined tongue rather than a chunky box)
spout_base_r = min(cr * 0.7, spout_w * 0.30);
spout_tip_r  = min(cr * 0.5, tip_w * 0.45);

// ---- Outer: dish (separate) + tapered tongue spout (separate) ----
module dish_only() {
    hull() {
        for (x = [cr, w-cr]) for (y = [cr, d-cr])
            translate([x, y, 0]) cylinder(h=h, r=cr);
    }
}

module spout_only() {
    if (spout_l > 0) {
        hull() {
            // Base cylinders — placed so they overlap into the dish
            // front edge by ~spout_base_r (creates flared join, not a
            // hard step, while the dish silhouette stays intact)
            translate([w/2 - spout_w/2 + spout_base_r,
                       spout_base_r, 0])
                cylinder(h=h, r=spout_base_r);
            translate([w/2 + spout_w/2 - spout_base_r,
                       spout_base_r, 0])
                cylinder(h=h, r=spout_base_r);
            // Tip cylinders — forward of dish, narrower
            translate([w/2 - tip_w/2 + spout_tip_r,
                       -spout_l + spout_tip_r, 0])
                cylinder(h=h, r=spout_tip_r);
            translate([w/2 + tip_w/2 - spout_tip_r,
                       -spout_l + spout_tip_r, 0])
                cylinder(h=h, r=spout_tip_r);
        }
    }
}

// ---- Cavities: same construction, inset by `wall` ----
module dish_cavity() {
    cr_in = max(1, cr - wall);
    hull() {
        for (x = [cr, w-cr]) for (y = [cr, d-cr])
            translate([x, y, floor]) cylinder(h=h+1, r=cr_in);
    }
}

module spout_cavity() {
    if (spout_l > 0) {
        base_in_r = max(1, spout_base_r - wall);
        tip_in_r  = max(1, spout_tip_r - wall);
        hull() {
            // Base — inset
            translate([w/2 - spout_w/2 + wall + base_in_r,
                       wall + base_in_r, floor])
                cylinder(h=h+1, r=base_in_r);
            translate([w/2 + spout_w/2 - wall - base_in_r,
                       wall + base_in_r, floor])
                cylinder(h=h+1, r=base_in_r);
            // Tip — pushed PAST the outer's tip by 1mm so the front
            // face of the spout is fully open (water exits)
            translate([w/2 - tip_w/2 + wall + tip_in_r,
                       -spout_l - 1, floor])
                cylinder(h=h+1, r=tip_in_r);
            translate([w/2 + tip_w/2 - wall - tip_in_r,
                       -spout_l - 1, floor])
                cylinder(h=h+1, r=tip_in_r);
        }
    }
}

// ---- Final dish ----
difference() {
    union() {
        dish_only();
        spout_only();
    }
    union() {
        dish_cavity();
        spout_cavity();
    }
}

// ---- Drain ridges — rounded-top capsules ----
ridge_sp = (w - wall*2 - 8) / (ridges - 1);
ridge_r  = 1.6;
ridge_y0 = wall + 4;
ridge_y1 = d - wall - 4;
for (i = [0:ridges-1]) {
    rx = wall + 4 + i * ridge_sp;
    hull() {
        translate([rx, ridge_y0, floor + 0.2])
            sphere(r=ridge_r);
        translate([rx, ridge_y1, floor + 0.2])
            sphere(r=ridge_r);
    }
}

spool_holder.scad_template:
// Parametric Spool Holder
// One-piece bench stand: the spool rides on two half-round rails.
// Each rail is a support wall capped by a rod clipped at its
// 45-degree tangent planes, so no surface overhangs; rail height is
// computed from the spool diameter so the spool bottom always clears
// the base.  (The old geometry had bare posts and nothing for a
// spool to rest on at all.)
sw = ${spool_width};
sd = ${spool_dia};
rd = ${roller_dia};
wall = ${wall};

base_w = sw + wall * 4;
base_d = sd * 0.6;
base_h = wall;

r = rd / 2;
R = sd / 2;
s = sd * 0.35;                    // rail center spacing
// How far the spool center sits above the rail axes when resting
// tangent on both rails
drop = sqrt(pow(R + r, 2) - pow(s / 2, 2));
// Lift the rails so the spool bottom clears the base by >= 3 mm
lift = max(2, R + 3 - drop);
rail_c = base_h + lift + r;       // rail axis height
half_w = r * 0.707;               // 45-degree tangent half-chord

module rail() {
    // Support wall under the rod, exactly as wide as the 45-degree
    // tangent chord so the rod meets it with no overhang
    translate([0, -half_w, 0])
        cube([base_w, half_w * 2, rail_c]);
    // Rod clipped at the tangent planes: vertical sides below,
    // a <=45-degree arc on top for the spool to ride
    intersection() {
        translate([0, 0, rail_c])
            rotate([0, 90, 0])
                cylinder(h = base_w, r = r, $fn = 48);
        translate([0, -half_w, rail_c - r])
            cube([base_w, half_w * 2, r * 2]);
    }
}

module spool_holder() {
    // Base plate
    cube([base_w, base_d, base_h]);
    // Side walls keep the spool from walking off the rail ends
    for (x = [0, base_w - wall])
        translate([x, 0, 0])
            cube([wall, base_d, rail_c + r + 10]);
    // Rails
    for (y = [base_d / 2 - s / 2, base_d / 2 + s / 2])
        translate([0, y, 0])
            rail();
}

spool_holder();

tube_connector.scad_template:
// Parametric Tube Connector
tod = ${tube_od};
wall = ${wall};
len = ${length};
ang = ${angle};

od = tod + wall * 2;
bend_r = od * 2;

module connector() {
    if (ang == 0) {
        // Straight connector
        difference() {
            cylinder(h=len*2, d=od, $fn=50, center=true);
            cylinder(h=len*2+2, d=tod + 0.4, $fn=50, center=true);
        }
    } else {
        // Angled connector
        difference() {
            union() {
                cylinder(h=len, d=od, $fn=50);
                translate([0, 0, len])
                    rotate([ang, 0, 0])
                        cylinder(h=len, d=od, $fn=50);
                // Elbow joint
                translate([0, 0, len])
                    sphere(d=od, $fn=50);
            }
            union() {
                cylinder(h=len+1, d=tod + 0.4, $fn=50);
                translate([0, 0, len])
                    rotate([ang, 0, 0])
                        cylinder(h=len+1, d=tod + 0.4, $fn=50);
                translate([0, 0, len])
                    sphere(d=tod + 0.4, $fn=50);
            }
        }
    }
}

connector();

battery_holder.scad_template:
// Parametric Battery Holder
// Tray of half-round troughs.  The block top sits above the trough
// centerline, so each mouth is ~1.5 mm narrower than the battery
// and the curved lips snap-retain it (they stay under the 45-degree
// overhang limit).  A finger-scoop valley across the middle widens
// the mouths there for easy insertion and removal.
btype = "${battery_type}";
count = ${count};
wall = ${wall};

// Battery dimensions (diameter, length)
bd = (btype == "AAA") ? 10.5 : (btype == "18650") ? 18.6 : 14.5;
bl = (btype == "AAA") ? 44.5 : (btype == "18650") ? 65 : 50.5;

slot_w = bd + 1;
total_w = count * (slot_w + wall) + wall;
r = (bd + 0.5) / 2;
cz = bd / 2 + wall;                    // trough centerline height
mouth_half = bd / 2 - 0.75;            // mouth is bd - 1.5 wide
top = cz + sqrt(r * r - mouth_half * mouth_half);

module holder() {
    difference() {
        cube([total_w, bl + 1 + wall * 2, top]);
        for (i = [0:count - 1]) {
            // Battery trough; the rim lips retain the battery
            translate([wall + i * (slot_w + wall) + slot_w / 2, wall, cz])
                rotate([-90, 0, 0])
                    cylinder(h = bl + 1, d = bd + 0.5, $fn = 40);
        }
        // Finger scoop: a valley across the top at mid-length opens
        // the mouths wide enough to tilt a battery in or lift it out
        translate([-0.1, wall + bl / 2, top])
            rotate([0, 90, 0])
                cylinder(h = total_w + 0.2, d = bd, $fn = 40);
    }
}

holder();

wrench.scad_template:
