w = ${width};
t = ${thickness};
hd = ${hole_dia};
hn = ${holes_per_arm};

module brace() {
    difference() {
        union() {
            cube([al, w, t]);
            cube([t, w, al]);
            // Two edge webs brace the corner and leave the
            // centerline screw holes and driver paths clear
            for (y = [0, w - 3])
                translate([0, y + 3, 0])
                    rotate([90, 0, 0])
                        linear_extrude(3)
                            polygon([[t, t], [al*0.55, t], [t, al*0.55]]);
        }
        // Horizontal arm holes
        for (i = [1:hn]) {
            translate([t + (al-t) * i/(hn+1), w/2, -0.1])
                cylinder(h=t+0.2, d=hd, $fn=20);
        }
        // Vertical arm holes
        for (i = [1:hn]) {
            translate([-0.1, w/2, t + (al-t) * i/(hn+1)])
                rotate([0, 90, 0])
                    cylinder(h=t+0.2, d=hd, $fn=20);
        }
    }
}

