din_rail_clip.scad_template:
// Parametric DIN Rail Clip (35 mm standard)
// The clip's cross-section — back plate, bottom hook, sprung top
// hook, both lips reaching INTO the channel — is one 2D profile
// extruded to the mount width, so it prints flat with the layer
// lines wrapping the hooks.  The module mounts on the flat back
// face; the rail seats in the open channel from the front.  (The
// old geometry stood its mounting plate across the middle of the
// rail channel — no rail could ever seat.)
mw = ${mount_width};
mh = ${mount_height};
wall = ${wall};

rail_w = 35;      // rail span (vertical when installed)
rail_h = 7.5;     // rail depth off the wall
lip = 1.5;

plate_h = max(mh, rail_w + wall * 2);
arm_len = wall + rail_h + wall;     // arms reach past the rail depth

module profile() {
    // Back plate: flat mounting face at y = 0
    square([wall, plate_h]);
    // Bottom arm under the rail, lip hooking up over its edge
    square([arm_len, wall]);
    translate([wall + rail_h, wall])
        square([wall, lip + wall * 0.5]);
    // Top arm over the rail, lip hooking down — sprung by a relief
    // notch where it meets the plate
    translate([0, wall + rail_w])
        square([arm_len, wall]);
    translate([wall + rail_h, wall + rail_w - lip - wall * 0.5])
        square([wall, lip + wall * 0.5]);
}

module clip() {
    difference() {
        linear_extrude(mw) profile();
        // Spring relief: thins the top arm's root so it can flex
        // open while the rail snaps past the lip
        translate([wall - 0.1, wall + rail_w - 0.6, -0.1])
            cube([1.2, 0.6, mw + 0.2]);
    }
}

clip();

servo_bracket.scad_template:
// Parametric Servo Bracket
// U-channel around the servo body with a front apron the mounting
// screws pass through — clear of the channel walls (the old holes
// sat directly beneath them and could not take a screw).
sw = ${servo_width};
sd = ${servo_depth};
sh = ${servo_height};
tw = ${tab_width};
wall = ${wall};

clear = 0.5;
cw = sw + wall * 2 + clear * 2;   // channel outer width
cd = sd + wall + clear;           // channel outer depth
apron = 12;

module bracket() {
    difference() {
        union() {
            // U-channel for the servo
            cube([cw, cd, sh + wall]);
            // Base flange with a front apron for the screws
            translate([-(tw - cw) / 2, 0, 0])
                cube([max(tw, cw), cd + apron, wall]);
        }
        // Servo cavity
        translate([wall, wall, wall])
            cube([sw + clear * 2, sd + clear + 1, sh + 1]);
        // Mounting holes in the apron, clear of the channel
        for (x = [cw * 0.2, cw * 0.8])
            translate([x, cd + apron / 2, -0.1])
                cylinder(h = wall + 0.2, d = 3.2, $fn = 20);
    }
}

