stackable_bin.scad_template:
// Parametric Stackable Bin
w = ${width};
d = ${depth};
h = ${height};
wall = ${wall};
label = ${label_slot};

lip = 2;

module bin() {
    difference() {
        union() {
            // Outer shell
            cube([w, d, h]);
            // Stacking lip (extends above)
            translate([wall, wall, h])
                difference() {
                    cube([w - wall * 2, d - wall * 2, lip]);
                    translate([wall, wall, -0.1])
                        cube([w - wall * 4, d - wall * 4, lip + 0.2]);
                }
        }
        // Inner cavity; the floor sits above the stacking groove so
        // a full wall thickness remains over it
        translate([wall, wall, wall + lip + 0.2])
            cube([w - wall * 2, d - wall * 2, h - wall - lip - 0.2]);
        // Stacking groove at the bottom: clears the lip of the bin
        // below with 0.3 mm on both sides
        translate([wall - 0.3, wall - 0.3, -0.1])
            difference() {
                cube([w - wall * 2 + 0.6, d - wall * 2 + 0.6, lip + 0.3]);
                translate([wall + 0.6, wall + 0.6, -0.1])
                    cube([w - wall * 4 - 0.6, d - wall * 4 - 0.6, lip + 0.5]);
            }
    }
    // Label card pocket on the front wall: two L-rails and a ledge
    // hold a paper card.  Undersides ramp at 45 degrees so the
    // pocket prints without supports.
    if (label == 1) {
        card_w = w * 0.7;
        card_x = w * 0.15;
        pocket_lo = h * 0.45;
        pocket_hi = h * 0.85;
        rail_t = 2;
        lip_t = 1.2;   // front lip thickness
        gap = 1.2;     // card channel depth off the wall
        prot = gap + lip_t;
        rail_h = pocket_hi - pocket_lo;
        for (side = [0, 1])
            translate([side == 0 ? card_x - rail_t
                                 : card_x + card_w + rail_t, 0, 0])
            mirror([side, 0, 0]) {
                // upright L-rail: stand-off leg plus a lip that
                // traps the card edge in a channel against the wall
                translate([0, 0, pocket_lo])
                    linear_extrude(rail_h)
                        polygon([[0, 0], [0, -prot],
                                 [rail_t + 4, -prot],
                                 [rail_t + 4, -gap],
                                 [rail_t, -gap], [rail_t, 0]]);
                // sloped transition from the wall to the rail bottom
                hull() {
                    translate([0, -prot, pocket_lo - 0.2])
                        cube([rail_t + 4, prot, 0.2]);
                    translate([0, -0.4, pocket_lo - prot])
                        cube([rail_t + 4, 0.4, 0.2]);
                }
            }
        // bottom ledge the card rests on, with the same slope back
        // to the wall so it prints without supports
        hull() {
            translate([card_x, -prot, pocket_lo - 0.2])
                cube([card_w, prot, 0.2]);
            translate([card_x, -0.4, pocket_lo - prot])
                cube([card_w, 0.4, 0.2]);
        }
    }
}

bin();

threaded_jar.scad_template:
// Parametric Threaded Jar
d = ${diameter};
h = ${height};
wall = ${wall};
pitch = ${thread_pitch};

thread_h = 12;
thread_depth = 1.2;
clearance = 0.25;               // radial jar<->lid clearance
half = pitch * 0.45;            // thread half-height (axial)
depth = min(thread_depth, half); // keeps flanks at or under 45 degrees

// One continuous swept helical ridge: short prism stations along the
// helix, hulled pairwise into a smooth thread.  Profile is a triangle
// in the radial-axial plane -> printable flanks, no support needed.
// The sweep is inset by `half` at both ends so the thread stays flush
// with the part (max Z never exceeds the body height).
// pointing_out=true: ridge grows outward from radius r (jar OD).
// pointing_out=false: ridge grows inward from radius r (lid bore).
module helical_thread(r, length, pointing_out) {
    turns = (length - 2 * half) / pitch;
    steps = ceil(turns * 36);
    tip = pointing_out ? depth : -depth;
    for (i = [0:steps-1]) {
        hull() {
            for (k = [0, 1]) {
                a = 360 * turns * (i + k) / steps;
                translate([0, 0, half + a / 360 * pitch])
                    rotate([0, 0, a])
                        translate([r, 0, 0])
                            rotate([90, 0, 0])
                                linear_extrude(height = 0.01, center = true)
                                    polygon([[0, -half], [tip, 0], [0, half]]);
            }
        }
    }
}

module jar() {
    difference() {
        cylinder(h = h, d = d, $fn = 60);
        translate([0, 0, wall])
            cylinder(h = h, d = d - wall * 2, $fn = 60);
    }
    // External thread near the top, ends flush with the rim
    translate([0, 0, h - thread_h])
        helical_thread(d / 2, thread_h, true);
}

module lid() {
    bore = d + 2 * (thread_depth + clearance);
    translate([d + wall * 2 + thread_depth * 2 + clearance + 12, 0, 0]) {
        difference() {
            cylinder(h = thread_h + wall, d = bore + wall * 2, $fn = 60);
            translate([0, 0, wall])
                cylinder(h = thread_h + 1, d = bore, $fn = 60);
        }
        // Matching internal thread inside the skirt
        translate([0, 0, wall])
            helical_thread(bore / 2, thread_h, false);
    }
}

jar();
lid();

monitor_riser_shelf.scad_template:
// Parametric Monitor Riser
// Prints upside down: shelf flat on the bed, legs and back panel
// rising as plain walls.  Flip over to use.  No supports.
w = ${width};
d = ${depth};
h = ${height};
t = ${thickness};
lw = ${leg_width};

module riser() {
    // Shelf (top surface in use) on the bed
    cube([w, d, t]);
    // Legs rising from the shelf
    for (x = [0, w - lw]) {
        translate([x, 0, t])
            cube([lw, t, h - t]);
        translate([x, d - t, t])
            cube([lw, t, h - t]);
    }
    // Center legs pick up the span on wide risers
    if (w > 300)
        for (y = [0, d - t])
            translate([(w - lw) / 2, y, t])
                cube([lw, t, h - t]);
    // Back panel for stability
    translate([0, d - t, t])
        cube([w, t, h - t]);
}

riser();

tablet_stand.scad_template:
// Parametric Tablet Stand
// Back support rises at the requested angle from mid-base; solid
// side gussets brace it against tablet weight.
w = ${width};
ang = ${angle};
bd = ${base_depth};
t = ${thickness};
lip = ${lip_height};

back_len = bd * 0.8;
// Foot placed so the support face plane passes through the lip's
// inner top edge — same fix as phone_stand: a mid-base foot made the
// real resting angle ~47 degrees whatever `ang` was set to.
foot_y = max(2, t - (lip - t * cos(ang)) * cos(ang) / sin(ang));
gusset = min(30, bd * 0.25);

module stand() {
    // Base
    cube([w, bd, t]);
    // Front lip
    cube([w, t, lip]);
    // Back support: inclined at `ang` above the bed, sunk into the
    // base for a solid joint, with a cable pass-through notch at
    // the bottom center
    translate([0, foot_y, t * cos(ang)])
        rotate([ang - 90, 0, 0])
            difference() {
                cube([w, t, back_len]);
                // Cable notch at the bottom center, peaked at 45
                // degrees so the slab above it prints bridge-free
                translate([w / 2, -0.1, 0])
                    rotate([-90, 0, 0])
                        linear_extrude(t + 0.2)
                            polygon([[-10, 0.1], [10, 0.1], [10, -12],
                                     [0, -22], [-10, -12]]);
            }
    // Side gussets (45-degree hypotenuse, printable)
    for (x = [0, w - t])
        translate([x, foot_y + t * 0.5, 0])
            rotate([90, 0, 90])
                linear_extrude(t)
                    polygon([[0, 0], [gusset, 0], [0, gusset]]);
}

stand();

