bag_clip.scad_template:
// Parametric Bag Clip
// Two flat parts, printed side by side: a fold-over clip (two
// coplanar jaws joined by a top-surface living hinge) and a slider
// ring.  Fold the bag inside the clip, then push the slider over
// the closed end to lock it.
w = ${width};
jd = ${jaw_depth};
t = ${thickness};

hinge_gap = 2;
hinge_t = 0.8;      // living hinge: thin by design, fold at the seam
ridge_h = 0.8;
slider_wall = 3.5;
slider_band = 8;    // slider width along the clip
slot_h = 2 * t + 1.4;  // folded stack: two jaws + interleaved ridges
slot_w = w + 1;

module ridges(y0, y1, phase) {
    // Grip bars on the top face; the two jaws' bars are offset by
    // half a period so they interleave when the clip is folded shut.
    for (y = [y0 + 4 + phase : 8 : y1 - 4]) {
        translate([0, y, t])
            cube([w, 2, ridge_h]);
    }
}

module clip() {
    cube([w, jd, t]);
    ridges(0, jd, 0);
    // Living hinge at the top surface, so the top faces meet when
    // folded.  Prints as a short 2 mm bridge.
    translate([0, jd, t - hinge_t])
        cube([w, hinge_gap, hinge_t]);
    translate([0, jd + hinge_gap, 0])
        cube([w, jd, t]);
    ridges(jd + hinge_gap, jd + hinge_gap + jd, 4);
}

module slider() {
    // Closed rectangular band; the window slides over the folded
    // clip.  Prints window-up: every wall is vertical.
    difference() {
        translate([-slider_wall, -slot_h / 2 - slider_wall, 0])
            cube([slot_w + slider_wall * 2,
                  slot_h + slider_wall * 2, slider_band]);
        translate([-0.5, -slot_h / 2, -0.1])
            cube([slot_w, slot_h, slider_band + 0.2]);
    }
}

clip();
translate([0, -slider_wall - slot_h / 2 - 4, 0])
    slider();

spice_jar_rack.scad_template:
// Parametric Spice Rack
// Stepped tiers built as solid blocks that reach the bed, so every
// tier is supported.  Jar recesses are cut from the top of each step.
