jpr = ${jars_per_row};
rows = ${rows};
sh = ${step_height};
wall = ${wall};

total_w = jpr * (jd + wall) + wall;
row_d = jd + wall * 2;

module rack() {
    for (r = [0:rows - 1]) {
        step_top = wall + sh + r * sh;
        translate([0, r * row_d, 0])
            difference() {
                cube([total_w, row_d, step_top]);
                // Jar recesses, sh deep from the top of the step
                for (j = [0:jpr - 1]) {
                    translate([wall + j * (jd + wall) + jd / 2,
                               row_d / 2, step_top - sh])
                        cylinder(h = sh + 1, d = jd + 0.5, $fn = 40);
                }
            }
    }
}

