bottle_opener.scad_template:
// Parametric Bottle Opener
// One flat piece: a rounded handle flowing into a ring head.  The
// ring encloses a standard 26.5 mm crown cap with 1 mm of tilt
// clearance; a catch tooth on the handle side hooks under the cap
// lip and the far rim is the fulcrum.  (The old geometry cut the cap
// hole wider than the head, severing the tip and leaving the lever
// lip as a loose floating cube.)
l = ${length};
w = ${width};
t = ${thickness};

cap_d = 26.5;            // standard crown cap
wall = 5;
hr = cap_d / 2 + wall;   // head outer radius
tooth = 2.2;             // catch-tooth reach into the opening

module opener() {
    linear_extrude(height = t) {
        union() {
            difference() {
                union() {
                    // Handle
                    hull() {
                        translate([w / 2, 0]) circle(d = w, $fn = 40);
                        translate([l - hr, 0])
                            circle(d = w * 0.8, $fn = 40);
                    }
                    // Ring head
                    translate([l, 0]) circle(r = hr, $fn = 60);
                }
                // Cap opening, oversized 1 mm so the opener can tilt
                translate([l, 0]) circle(d = cap_d + 1, $fn = 60);
            }
            // Catch tooth reaching into the opening, rooted in the
            // solid handle-head junction
            translate([l - cap_d / 2 - 1, 0])
                polygon([[0, -3.5], [1 + tooth, -1.2],
                         [1 + tooth, 1.2], [0, 3.5]]);
        }
    }
}

opener();

filament_guide.scad_template:
// Parametric Filament Guide Clip
// The clip's cross-section -- C-clip around the extrusion, side
// entry opening with snap lips, guide arm with a teardrop tube
// hole -- is one 2D profile extruded to the clip width.  Prints
// flat with no supports; layer lines wrap the C so the snap flexes
// along the plastic, not across layers.
es = ${extrusion_size};
tid = ${tube_id};
al = ${arm_length};
wall = ${wall};

clip_w = 15;
arm_w = tid + wall * 2;
// Tube hole center, up the arm from the top of the clip body
hole_y = es + wall * 2 + al - arm_w / 2;

module teardrop(d) {
    // Circle plus a 45-degree roof so the horizontal hole prints
    // cleanly without support
    r = d / 2;
    circle(r = r, $fn = 30);
    polygon([[-r * 0.707, r * 0.707], [0, r * 1.414],
             [r * 0.707, r * 0.707]]);
}

module profile() {
    difference() {
        union() {
            // Clip body around the extrusion
            square([es + wall * 2, es + wall * 2]);
            // Guide arm rising from the top, with a rounded end
            translate([es / 2 + wall - arm_w / 2, es + wall * 2 - 0.1])
                square([arm_w, al - arm_w / 2 + 0.1]);
            translate([es / 2 + wall, hole_y])
                circle(d = arm_w, $fn = 30);
        }
        // Extrusion pocket
        translate([wall, wall])
            square([es + 0.5, es + 0.5]);
        // Side entry opening with snap lips (clips onto the rail)
        translate([-0.1, wall + es * 0.075])
            square([wall + 0.2, es * 0.85]);
        // Tube hole
        translate([es / 2 + wall, hole_y])
            teardrop(tid);
    }
}

linear_extrude(clip_w) profile();

nozzle_rack.scad_template:
// Parametric Nozzle Rack
n = ${slots};
nd = ${nozzle_dia};
depth = ${depth};
wall = ${wall};

spacing = nd + wall;
total_w = n * spacing + wall;
total_d = nd + wall * 2;
base_h = 3;

module rack() {
    difference() {
        cube([total_w, total_d, depth + base_h]);
        for (i = [0:n-1]) {
            translate([wall + i * spacing + nd/2, total_d/2, base_h])
                cylinder(h=depth + 1, d=(nd + 0.3) / cos(30), $fn=6);
        }
    }
}

rack();

cable_raceway_clip.scad_template:
// Parametric Cable Raceway Clip
// The clip's cross-section (base, gusseted throat, snap C-ring) is
// drawn as a 2D profile and extruded upward, so the whole part is
// vertical walls on the bed -- no supports, and the layer lines run
// around the C for maximum spring strength.
cd = ${cable_dia};
mw = ${mount_width};
wall = ${wall};
sh = ${screw_hole};

or = cd / 2 + wall;
cx = or;           // ring center x (over the base middle)
cy = wall + or;    // ring center y (above the base)
open = or;         // entry slot width (narrower than the cable)

module clip() {
    difference() {
        union() {
            linear_extrude(mw)
                difference() {
                    union() {
                        // Mounting base
                        square([or * 2, wall]);
                        // C-ring
                        translate([cx, cy]) circle(r = or, $fn = 40);
                        // Gusset joining ring to base
                        translate([cx - or * 0.75, wall - 0.1])
                            square([or * 1.5, or * 0.45]);
                    }
                    // Bore and entry slot cut from ring AND gusset
                    translate([cx, cy]) circle(r = cd / 2, $fn = 40);
                    translate([cx - open / 2, cy])
                        square([open, or + 1]);
                }
        }
        // Screw hole bored from the bore floor down through the
        // gusset and base — the driver reaches it through the top
        // entry slot and the bore
        translate([cx, cy - cd / 2 + 0.1, mw / 2])
            rotate([90, 0, 0])
                cylinder(h = cy - cd / 2 + 0.3, d = sh, $fn = 20);
    }
}

clip();

cable_grommet.scad_template:
// Parametric Cable Grommet
// Prints flange-down: flange on the bed, sleeve rising, snap ring
// at the top with a 45-degree lead-in so no supports are needed.
hd = ${hole_dia};
dt = ${desk_thickness};
csw = ${cable_slot_width};

flange = 5;
wall = 2;
flange_t = 3;
snap_t = 2;

module grommet() {
    difference() {
        union() {
            // Flange (desk-top face) on the bed
            cylinder(h = flange_t, d = hd + flange * 2, $fn = 60);
            // Sleeve rising through the desk hole, 0.4 mm under
            // the hole so it can actually be inserted
            translate([0, 0, flange_t])
                difference() {
                    cylinder(h = dt, d = hd - 0.4, $fn = 60);
                    translate([0, 0, -0.1])
                        cylinder(h = dt + 0.2, d = hd - wall * 2, $fn = 60);
                }
            // Snap ring PAST the desk's far face: lead-in cone, then
            // the retaining ledge expands under the desk.  (The old
            // ledge topped out level with the desk face — it stayed
            // compressed in the hole and never engaged.)
            translate([0, 0, flange_t + dt])
                difference() {
                    union() {
                        cylinder(h = 1.2, d1 = hd - 0.4, d2 = hd + 1.6, $fn = 60);
                        translate([0, 0, 1.2])
                            cylinder(h = snap_t, d = hd + 1.6, $fn = 60);
                    }
                    translate([0, 0, -0.1])
                        cylinder(h = snap_t + 1.4, d = hd - wall * 2, $fn = 60);
                }
        }
        // Cable pass: radial slot from the edge to a central opening.
        // Runs to the center only, so the ring stays in one piece.
        translate([-csw / 2, -hd / 2 - flange - 1, -0.1])
            cube([csw, hd / 2 + flange + 1, flange_t + dt + snap_t + 1.4]);
        translate([0, 0, -0.1])
            cylinder(h = flange_t + dt + snap_t + 1.4, d = max(csw, hd - wall * 2), $fn = 60);
    }
}

grommet();

gopro_mount.scad_template:
// GoPro Mount Adapter
// Standard 3-finger GoPro mount base.  Finger geometry follows the
// community-measured standard: 3.0 mm fingers, 3.1 mm gaps, 5.2 mm
// pivot hole, rounded finger ends.  The pivot hole is a teardrop so
// it prints horizontally without supports.
bw = ${base_width};
bd = ${base_depth};
bt = ${base_thickness};

finger_t = 3.0;
gap = 3.25;
pitch = finger_t + gap;
hole_d = 5.2;
end_r = 7.4;               // rounded finger end radius
hole_z = 8.2;              // hole center above the base

module finger_profile() {
    difference() {
        union() {
            translate([-end_r, 0]) square([end_r * 2, hole_z]);
            translate([0, hole_z]) circle(r = end_r, $fn = 40);
        }
        // Teardrop pivot hole: circle plus a 45-degree roof
        translate([0, hole_z]) {
            circle(d = hole_d, $fn = 30);
            polygon([[-hole_d / 2 * 0.707, hole_d / 2 * 0.707],
                     [0, hole_d / 2 * 1.414],
                     [hole_d / 2 * 0.707, hole_d / 2 * 0.707]]);
        }
    }
}

module finger() {
    rotate([90, 0, 90])
        linear_extrude(finger_t)
            finger_profile();
}

module mount() {
    // Base plate
    translate([-bw / 2, -bd / 2, 0])
        cube([bw, bd, bt]);
    // Three fingers on the standard pitch
    for (i = [-1, 0, 1])
        translate([i * pitch - finger_t / 2, 0, bt])
            finger();
}

mount();

vesa_adapter.scad_template:
// VESA Adapter Plate
fs = ${from_spacing};
ts = ${to_spacing};
t = ${thickness};
bd = ${bolt_dia};

plate_s = max(fs, ts) + 20;

module adapter() {
    difference() {
        translate([-plate_s/2, -plate_s/2, 0])
            cube([plate_s, plate_s, t]);
        // Source pattern: through-holes with head counterbores so
        // the target plate can seat flush over them
        for (x = [-fs/2, fs/2])
            for (y = [-fs/2, fs/2])
                translate([x, y, -0.1]) {
                    cylinder(h=t+0.2, d=bd, $fn=20);
                    translate([0, 0, t - 2.4])
                        cylinder(h=2.6, d=bd*1.9, $fn=24);
                }
        // Target pattern (through-holes)
        for (x = [-ts/2, ts/2])
            for (y = [-ts/2, ts/2])
                translate([x, y, -0.1])
                    cylinder(h=t+0.2, d=bd, $fn=20);
    }
}

adapter();

rail_clamp.scad_template:
// Parametric Rail Clamp
// The clamp's cross-section (split ring, bolt ears, mounting pad)
// is a 2D profile extruded upward: every wall prints vertical, and
// the clamping bolt crosses the split so tightening it actually
// closes the ring.
rd = ${rail_dia};
cw = ${clamp_width};
wall = ${wall};
bd = ${bolt_dia};
mh = ${mount_holes};

or = rd / 2 + wall;
bore_r = rd / 2 + 0.25;    // bore radius (0.5 mm dia clearance)
ear_len = wall * 2 + bd;   // ears reach past the ring for the bolt
slit = 1;

module clamp() {
    difference() {
        linear_extrude(cw)
            union() {
                difference() {
                    // Ring
                    circle(r = or, $fn = 60);
                    // Rail bore
                    circle(d = rd + 0.5, $fn = 60);
                }
                // Bolt ears flanking the split, rooted in the ring
                // band and starting OUTSIDE the bore
                for (s = [-1, 1])
                    translate([bore_r + 0.75, s == 1 ? slit / 2 : -slit / 2 - wall])
                        square([or - bore_r - 0.75 + ear_len, wall]);
                // Mounting pad: flat face at x = -or, its depth held
                // outside the bore
                translate([-or, -or * 0.7])
                    square([or - bore_r - 0.3, or * 1.4]);
            }
        // Split gap through ring and between the ears
        translate([or * 0.3, -slit / 2, -0.1])
            cube([or + ear_len + 0.2, slit, cw + 0.2]);
        // Clamping bolt across the split
        translate([or + ear_len / 2, or, cw / 2])
            rotate([90, 0, 0])
                cylinder(h = or * 2, d = bd, $fn = 20);
        // Mounting holes through the pad — teardrop section so the
        // horizontal bores print without supports
        for (i = [1:mh])
            translate([-or - 0.1, 0, cw * i / (mh + 1)])
                rotate([0, 90, 0])
                    linear_extrude(or - bore_r + 0.2) {
                        circle(d = bd * 0.8, $fn = 20);
                        polygon([[-bd * 0.283, -bd * 0.283],
                                 [-bd * 0.566, 0],
                                 [-bd * 0.283, bd * 0.283]]);
                    }
    }
}

clamp();

plant_label_stake.scad_template:
// Parametric Plant Label Stake
// Prints lying flat: the label, blade, and point are one 2D outline
// extruded to thickness, with the text raised on the top face.
// Flat layers also run along the stake, so pushing it into soil
// loads the plastic along the layers instead of across them.
lw = ${label_width};
lh = ${label_height};
sl = ${stake_length};
t = ${thickness};
txt = "${text_string}";

module stake() {
    // Outline: point, tapering blade, label plate
    linear_extrude(t)
        polygon([[lw / 2 - 0.75, 0],
                 [lw / 2 + 0.75, 0],
                 [lw / 2 + t * 1.5, 15],
                 [lw, sl],
                 [lw, sl + lh],
                 [0, sl + lh],
                 [0, sl],
                 [lw / 2 - t * 1.5, 15]]);
    // Raised text on the label face, sized to fit and hard-clipped
    // to the plate so no glyph can ever hang off the edge
    txt_size = min(lh * 0.4, (lw - 8) / (0.78 * max(1, len(txt))));
    intersection() {
        translate([2, sl + 2, 0])
            cube([lw - 4, lh - 4, t + 1]);
        translate([lw / 2, sl + lh / 2, t])
            linear_extrude(0.8)
                text(txt, size = txt_size, halign = "center",
                     valign = "center",
                     font = "Liberation Sans:style=Bold");
    }
}

stake();

pot_drip_tray.scad_template:
// Parametric Drip Tray
pd = ${pot_dia};
rh = ${rim_height};
wall = ${wall};
margin = ${margin};

od = pd + margin * 2 + wall * 2;

module tray() {
    difference() {
        cylinder(h=rh, d=od, $fn=80);
        translate([0, 0, wall])
            cylinder(h=rh, d=od - wall * 2, $fn=80);
    }
}

tray();

seed_spacer.scad_template:
// Parametric Seed Spacer
gs = ${grid_spacing};
cols = ${cols};
rows = ${rows};
hd = ${hole_dia};
t = ${thickness};

margin = 10;
total_w = (cols - 1) * gs + margin * 2;
total_d = (rows - 1) * gs + margin * 2;

module spacer() {
    difference() {
        cube([total_w, total_d, t]);
        for (c = [0:cols-1])
            for (r = [0:rows-1])
                translate([margin + c * gs, margin + r * gs, -0.1])
                    cylinder(h=t+0.2, d=hd, $fn=20);
    }
}

spacer();

phone_vent_mount.scad_template:
// Parametric Phone Vent Mount
// Two flat parts, both printed without supports.  The cradle prints
// on its back (grips and ledge rise as walls); the vent fin prints
// on its side.  The fin's tongue slides through the slot in the
// cradle's plate until its flange seats, then the tongue hooks
// behind a vent slat -- the vent face traps the plate against the
// flange, and the phone's weight keeps the hook seated.
pw = ${phone_width};
gd = ${grip_depth};
vsw = ${vent_slot_width};
t = ${thickness};

body_h = 40;
tongue_len = 28;
fin_t = 9;                 // fin thickness (across the slot)
tongue_h = max(1.8, vsw * 0.9);
hook_drop = 1.6;

module cradle() {
    difference() {
        union() {
            // Back plate on the bed
            cube([pw + gd * 2, body_h, t]);
            // Side grips
            for (x = [0, pw + gd])
                translate([x, 0, 0])
                    cube([gd, body_h, gd]);
            // Bottom ledge (holds the phone's lower edge)
            translate([gd, 0, 0])
                cube([pw, t, gd * 0.6]);
        }
        // Fin slot through the plate
        translate([(pw + gd * 2 - fin_t - 0.4) / 2, body_h * 0.55, -0.1])
            cube([fin_t + 0.4, tongue_h + 0.4, t + 0.2]);
    }
}

module fin() {
    x0 = 4;                          // flange thickness
    x1 = x0 + t + 0.6 + tongue_len;  // tongue end / hook face
    linear_extrude(fin_t)
        polygon([
            [0, -4],                          // flange bottom
            [x0, -4],
            [x0, 0],                          // tongue underside
            [x1, 0],
            [x1, -hook_drop],                 // hook face (catches slat)
            [x1 + 1.5, -hook_drop],           // hook bottom
            [x1 + 1.5 + hook_drop + tongue_h, tongue_h],  // entry ramp
            [x0, tongue_h],                   // tongue top edge
            [x0, tongue_h + 4],               // flange top
            [0, tongue_h + 4],
        ]);
}

cradle();
// Fin printed beside the cradle, flat on its side
translate([(pw + gd * 2) / 2 + fin_t / 2, body_h + 8, 0])
    rotate([0, 0, 90])
        fin();

fuse_puller.scad_template:
// Parametric Fuse Puller
// Prints lying flat: the tweezer outline is a 2D profile extruded to
// thickness, so the arms flex in the layer plane instead of prying
// layers apart, and there is no tall skinny print to topple.
l = ${length};
fw = ${fuse_width};
t = ${thickness};

handle_w = 15;
tip_gap = fw + 1;
cx = handle_w / 2;

module puller() {
    linear_extrude(t)
        union() {
            // Left arm, necking in to its gripping tip
            hull() {
                square([handle_w / 2, l * 0.6]);
                translate([cx - tip_gap / 2 - 3, l - 8])
                    square([3, 8]);
            }
            // Right arm
            hull() {
                translate([handle_w / 2, 0])
                    square([handle_w / 2, l * 0.6]);
                translate([cx + tip_gap / 2, l - 8])
                    square([3, 8]);
            }
            // Bridge at the base
            square([handle_w, 5]);
        }
    // Grip ridges on the handle faces
    for (y = [10:8:l * 0.5])
        translate([0, y, t])
            cube([handle_w, 2, 1]);
}

puller();

corner_clamp_jig.scad_template:
// 90-Degree Corner Clamp Jig
al = ${arm_length};
aw = ${arm_width};
h = ${height};
t = ${thickness};

module jig() {
    // Inner corner block
    cube([aw, aw, h]);
    // Arm 1 (X direction)
    cube([al, t, h]);
    // Arm 2 (Y direction)
    cube([t, al, h]);
    // Base plate
    cube([al, al, t]);
    // Diagonal brace: a real wall between the two arms
    translate([aw, aw, 0])
        linear_extrude(height = h * 0.75)
            polygon([[0, 0], [(al - aw) * 0.6, 0], [0, (al - aw) * 0.6]]);
}

jig();

bench_dog.scad_template:
// Parametric Bench Dog
// Prints head-down: the wide head is on the bed, a 45-degree cone
// flares out to the shoulder, and the peg rises last.  The
// shoulder's seating face (which registers on the bench top in use)
// prints as a flat top surface.
hd = ${hole_dia};
ph = ${peg_height};
pd = ${peg_depth};
head = ${head_dia};

spring_cut = 1;
head_d = head * 0.8;
cone_h = (head - head_d) / 2 * 1.1;

module dog() {
    difference() {
        union() {
            // Above-surface head (on the bed)
            cylinder(h = ph - 3, d = head_d, $fn = 40);
            // Printable cone out to the shoulder
            translate([0, 0, ph - 3])
                cylinder(h = cone_h, d1 = head_d, d2 = head, $fn = 40);
            // Shoulder; its top face seats on the bench in use
            translate([0, 0, ph - 3 + cone_h])
                cylinder(h = 3, d = head, $fn = 40);
            // Below-surface peg
            translate([0, 0, ph + cone_h])
                cylinder(h = pd, d = hd + 0.4, $fn = 40);
        }
        // Spring slot for friction fit, cut down from the peg tip
        translate([-spring_cut / 2, -hd / 2, ph + cone_h + pd * 0.3])
            cube([spring_cut, hd, pd + 0.1]);
    }
}

dog();

hose_barb_adapter.scad_template:
// Parametric Hose Barb Adapter
// The whole body is one revolved profile (and the bore another), so
// there are no stacked-solid seams to leave artifacts.  Barbs are
// symmetric ~40-degree diamonds: printable without supports in
// either direction, and the ridge still bites under a hose clamp.
sid = ${small_id};
lid = ${large_id};
bl = ${barb_length};
wall = ${wall};

barb_h = 1.2;   // radial ridge height
barbs = 3;
step = bl / barbs;
// ~40 degrees on each barb face, capped so short barb sections
// keep a monotonic profile
rise = min(barb_h * 2 * 1.2, step * 0.45);
sod = sid + wall * 2;
lod = lid + wall * 2;
shoulder_d = max(sid, lid) + wall * 2 + barb_h * 2;
cone_h = (shoulder_d - sod) / 2 * 1.1;   // 45-degree cone under shoulder
z_top = bl + cone_h + 4;                 // large section start

// One barbed section as revolved-profile points, base at z0
function barb_pts(od, z0) = concat(
    [[od / 2, z0]],
    [for (i = [0:barbs - 1]) each [
        [od / 2, z0 + i * step + step - 2 * rise],
        [od / 2 + barb_h, z0 + i * step + step - rise],
        [od / 2, z0 + (i + 1) * step]]]);

module adapter() {
    difference() {
        rotate_extrude($fn = 60)
            polygon(concat(
                [[0, 0]],
                barb_pts(sod, 0),
                [[shoulder_d / 2, bl + cone_h],
                 [shoulder_d / 2, z_top]],
                barb_pts(lod, z_top),
                [[0, z_top + bl]]));
        // Bore: small end, 45-degree internal transition, large end
        rotate_extrude($fn = 60)
            polygon([[0, -0.1],
                     [sid / 2, -0.1],
                     [sid / 2, z_top - (lid - sid) / 2 * 1.1],
                     [lid / 2, z_top],
                     [lid / 2, z_top + bl + 0.1],
                     [0, z_top + bl + 0.1]]);
    }
}

adapter();

drain_strainer.scad_template:
// Parametric Drain Strainer
// The recessed disc sits in the drain; a 45-degree cone joins it to
// the rim, so the rim underside prints without supports and the
// strainer self-centers in the drain.
dd = ${drain_dia};
rim = ${rim_width};
slots = ${slot_count};
t = ${thickness};

od = dd + rim * 2;
slot_w = 2;
cone_h = (od - (dd - 1)) / 2 * 1.1;  // slightly steeper than 45

module strainer() {
    difference() {
        union() {
            // Recessed disc that sits inside the drain
            cylinder(h = 3, d = dd - 1, $fn = 60);
            // Printable cone transition out to the rim
            translate([0, 0, 3])
                cylinder(h = cone_h, d1 = dd - 1, d2 = od, $fn = 60);
            // Rim
            translate([0, 0, 3 + cone_h])
                cylinder(h = t, d = od, $fn = 60);
        }
        // Radial slots, kept inside the recessed disc.  The inner
        // start radius grows with slot count so neighboring slots
        // never merge near the center.
        slot_r0 = max(8, slots * slot_w / 6.28 * 1.6);
        for (a = [0:360 / slots:359]) {
            rotate([0, 0, a])
                translate([-slot_w / 2, slot_r0, -0.1])
                    cube([slot_w, max(2, dd / 2 - 3 - slot_r0),
                          3 + cone_h + t + 0.2]);
        }
        // Center hole
        translate([0, 0, -0.1])
            cylinder(h = 3 + cone_h + t + 0.2, d = 8, $fn = 20);
    }
}

strainer();

raspberry_pi_case.scad_template:
// Parametric RPi Case
// Two parts printed side by side, both open-face-up so neither has
// an unsupported ceiling.  Flip the lid over onto the base to close.
// Mounting standoffs follow the official Pi mechanical drawing:
// 58 x 49 mm hole pattern, 3.5 mm from the SD-card end and 3.5 mm
// from each long edge.
bw = ${board_width};
bd = ${board_depth};
bh = ${board_height};
wall = ${wall};
vents = ${vent_slots};

clear = 1;
ow = bw + clear * 2 + wall * 2;
od = bd + clear * 2 + wall * 2;
oh = bh + wall * 2 + 3;
// Official hole pattern (85x56 board): inset 3.5 from the SD end,
// spans 58 along the board; 3.5 from each long edge, spanning 49.
hole_span_y = 58;
hole_inset = 3.5;

module standoff() {
    difference() {
        cylinder(h = 3, d = 6, $fn = 20);
        translate([0, 0, -0.1])
            cylinder(h = 3.2, d = 2.7, $fn = 20);
    }
}

module case_bottom() {
    difference() {
        cube([ow, od, oh / 2]);
        translate([wall, wall, wall])
            cube([bw + clear * 2, bd + clear * 2, oh]);
        // Power / HDMI cutout (long side)
        translate([ow - wall - 0.1, wall + clear + 5, wall + 3])
            cube([wall + 0.2, 45, oh]);
        // SD card slot (short side, SD end); 45-degree peaked top
        // so the wall above it prints without a bridge
        translate([wall + bw / 2 - 6, -0.1, wall])
            cube([12, wall + 0.2, 3]);
        translate([wall + bw / 2, wall + 0.1, wall + 3])
            rotate([90, 0, 0])
                linear_extrude(wall + 0.2)
                    polygon([[-6, 0], [6, 0], [0, 6]]);
        // USB / Ethernet opening (short side opposite the SD end),
        // open through the top edge
        translate([wall + clear + 2, od - wall - 0.1, wall + 2])
            cube([bw - 4, wall + 0.2, oh]);
        // Ventilation: slots run through the top (mating) edge so
        // they print without ceilings
        if (vents == 1) {
            for (y = [wall + 5 : 4 : od - wall - 5]) {
                translate([-0.1, y, wall + 2])
                    cube([wall + 0.2, 2, oh / 2]);
            }
        }
    }
    // PCB standoffs on the official hole pattern
    for (x = [wall + clear + hole_inset, wall + clear + bw - hole_inset])
        for (y = [wall + clear + hole_inset,
                  wall + clear + min(hole_inset + hole_span_y,
                                     bd - hole_inset)])
            translate([x, y, wall])
                standoff();
}

module case_top() {
    // Printed roof-down (open face up); flip over onto the base.
    translate([ow + 10, 0, 0]) {
        difference() {
            cube([ow, od, oh / 2]);
            translate([wall, wall, wall])
                cube([bw + clear * 2, bd + clear * 2, oh / 2]);
            // USB / Ethernet notch: printed y-min wall lands on the
            // USB face when the lid is flipped over onto the base
            translate([wall + clear + 2, -0.1, oh / 2 - 10])
                cube([bw - 4, wall + 0.2, 10.1]);
        }
        // Registration tongue: rooted ON the wall top and leaning
        // inward at ~45 degrees, so its tip nests into the base
        // cavity when the lid is flipped on — no bridges, and the
        // slope doubles as the lead-in
        difference() {
            translate([ow / 2, od / 2, oh / 2])
                linear_extrude(max(2.5, (2 * wall - 1.4) / 2 * 1.15),
                    scale = [(bw + clear * 2 - 0.6) / (ow - 0.8),
                             (bd + clear * 2 - 0.6) / (od - 0.8)])
                    difference() {
                        square([ow - 0.8, od - 0.8], center = true);
                        square([ow - 4, od - 4], center = true);
                    }
            // The tongue skips the USB notch span — otherwise it
            // would bridge across the open notch below it
            translate([wall + clear + 1.5, -0.1, oh / 2 - 0.1])
                cube([bw - 3, 7, 6]);
        }
    }
}

case_bottom();
case_top();

switch_panel.scad_template:
