gear_spur.scad_template:
// Parametric Spur Gear
// The gear outline is the root disc plus the teeth and nothing else.
// (The old construction unioned a filler ring out to the tooth tips,
// which buried every tooth inside a smooth disc.)  Straight-flank
// trapezoidal teeth, flank angle from the pressure angle: not a true
// involute, but it meshes with its own kind at the same module.
n = ${teeth};
m = ${module_mm};
fw = ${face_width};
bd = ${bore_dia};
pa = ${pressure_angle};

pitch_r = n * m / 2;
outer_r = pitch_r + m;          // addendum: 1.0 * m
root_r = pitch_r - 1.25 * m;    // dedendum: 1.25 * m
// The bore can never swallow the root disc: at small tooth counts
// an unclamped bore left every tooth a floating fragment.
bd_eff = min(bd, 2 * root_r - 2 * max(1.2, m));

// Half tooth thickness at root and tip: half the circular pitch at
// the pitch circle, widened below it and narrowed above it by the
// pressure-angle flank slope.
hw_root = m * 3.14159 / 4 + 1.25 * m * tan(pa) - 0.08;
hw_tip = max(m * 0.1, m * 3.14159 / 4 - m * tan(pa) - 0.08);

module tooth() {
    polygon([
        [root_r - 0.5, -hw_root],
        [outer_r, -hw_tip],
        [outer_r, hw_tip],
        [root_r - 0.5, hw_root],
    ]);
}

module gear() {
    difference() {
        linear_extrude(height = fw) {
            circle(r = root_r, $fn = n * 4);
            for (i = [0:n-1])
                rotate([0, 0, i * 360 / n])
                    tooth();
        }
        // Center bore
        translate([0, 0, -0.1])
            cylinder(h = fw + 0.2, d = bd_eff, $fn = 30);
    }
}

gear();

pulley_gt2.scad_template:
// GT2 Timing Pulley
nt = ${teeth};
bd = ${bore_dia};
bw = ${belt_width};
fd = ${flange_dia};

pitch = 2; // GT2 = 2mm pitch
pr = nt * pitch / (2 * 3.14159);
or = pr + 0.25;
// Flanges must clear the tooth barrel or the barrel overhangs them
fde = max(fd, (or + 1.5) * 2);
fh = 1.5; // flange height
// 45-degree cone joining the barrel to the top flange, so the
// flange underside prints without supports
cone_h = max(0.6, (fde / 2 - or) * 1.1);

module pulley() {
    difference() {
        union() {
            // Bottom flange
            cylinder(h = fh, d = fde, $fn = 50);
            // Toothed section
            translate([0, 0, fh])
                cylinder(h = bw, r = or, $fn = nt * 2);
            // Printable cone up to the top flange
            translate([0, 0, fh + bw])
                cylinder(h = cone_h, r1 = or, r2 = fde / 2, $fn = 50);
            // Top flange
            translate([0, 0, fh + bw + cone_h])
                cylinder(h = fh, d = fde, $fn = 50);
        }
        // Bore
        translate([0, 0, -0.1])
            cylinder(h = bw + fh * 2 + cone_h + 0.2, d = bd, $fn = 30);
        // Teeth grooves (simplified)
        for (i = [0:nt - 1])
            rotate([0, 0, i * 360 / nt])
                translate([or, 0, fh - 0.1])
                    cylinder(h = bw + 0.2, d = 1.6, $fn = 16);
    }
}

pulley();

z_axis_guide.scad_template:
// Z-Axis Endstop Mount
sw = ${slot_width};
mh = ${mount_height};
eshw = ${switch_width};
t = ${thickness};

module mount() {
    difference() {
        union() {
            // Clamp body
            cube([20 + t*2, t, mh]);
            // Switch platform
            translate([20 + t*2, 0, 0])
                cube([eshw + t*2, t + 12, t]);
            // Rib tying the platform into the clamp body
            translate([20 + t*2 - t, 0, 0])
                cube([t * 2, t + 12, 12]);
        }
        // Extrusion slot
        translate([t + (20 - sw)/2, -0.1, mh/2 - 5])
            cube([sw, t + 0.2, 10]);
        // Switch mounting holes
        for (dx = [t + 4, t + eshw - 2])
            translate([20 + t*2 + dx, t + 6, -0.1])
                cylinder(h=t+0.2, d=2.5, $fn=15);
    }
}

